using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers)
        group.MapGet("/", async (ApplicationDbContext db, HttpContext http) =>
        {
            var user = http.User;
            var email = user.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
                ?? user.FindFirst(System.Security.Claims.ClaimTypes.Name)?.Value;

            var isDispatcher = user.IsInRole("Dispatcher");

            var query = db.Shipments.AsQueryable();

            if (!isDispatcher)
            {
                query = query.Where(s => s.CustomerEmail == email);
            }

            var shipments = await query
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Notes = s.Notes
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Track shipment by tracking number (public access)
        app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null)
                return Results.NotFound(new { message = "Shipment not found" });

            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                Notes = shipment.Notes
            });
        });

        // Create shipment (dispatchers only)
        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db, HttpContext http) =>
        {
            if (!http.User.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = dto.Status,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = dto.EstimatedDelivery,
                CustomerEmail = dto.CustomerEmail,
                Notes = dto.Notes,
                AssignedDispatcherId = http.User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            dto.Id = shipment.Id;
            dto.CreatedAt = shipment.CreatedAt;
            return Results.Created($"/api/shipments/{shipment.Id}", dto);
        });

        // Update shipment status (dispatchers only)
        group.MapPut("/{id}", async (int id, ShipmentDto dto, ApplicationDbContext db, HttpContext http) =>
        {
            if (!http.User.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            shipment.Status = dto.Status;
            shipment.Destination = dto.Destination;
            shipment.EstimatedDelivery = dto.EstimatedDelivery;
            shipment.Notes = dto.Notes;

            await db.SaveChangesAsync();
            return Results.NoContent();
        });

        // Delete shipment (dispatchers only)
        group.MapDelete("/{id}", async (int id, ApplicationDbContext db, HttpContext http) =>
        {
            if (!http.User.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null)
                return Results.NotFound();

            db.Shipments.Remove(shipment);
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }
}

