{"file_text": "@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid mt-4">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>📋 Dispatcher Dashboard</h2>
        <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>

    @if (errorMessage is not null)
    {
        <div class="alert alert-danger alert-dismissible">
            @errorMessage
            <button type="button" class="btn-close" @onclick="() => errorMessage = null"></button>
        </div>
    }

    @if (showForm)
    {
        <div class="card mb-4">
            <div class="card-header">
                <strong>@(editingShipment.Id == 0 ? "Create New Shipment" : "Edit Shipment")</strong>
            </div>
            <div class="card-body">
                <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                    <DataAnnotationsValidator />
                    <div class="row">
                        <div class="col-md-4 mb-3">
                            <label class="form-label">Tracking Number</label>
                            <InputText class="form-control" @bind-Value="editingShipment.TrackingNumber" />
                        </div>
                        <div class="col-md-4 mb-3">
                            <label class="form-label">Origin</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Origin" />
                        </div>
                        <div class="col-md-4 mb-3">
                            <label class="form-label">Destination</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Destination" />
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-md-3 mb-3">
                            <label class="form-label">Status</label>
                            <InputSelect class="form-select" @bind-Value="editingShipment.Status">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </InputSelect>
                        </div>
                        <div class="col-md-3 mb-3">
                            <label class="form-label">Estimated Delivery</label>
                            <InputDate class="form-control" @bind-Value="editingShipment.EstimatedDelivery" />
                        </div>
                        <div class="col-md-3 mb-3">
                            <label class="form-label">Customer Email</label>
                            <InputText class="form-control" @bind-Value="editingShipment.CustomerEmail" />
                        </div>
                        <div class="col-md-3 mb-3">
                            <label class="form-label">Notes</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Notes" />
                        </div>
                    </div>
                    <button type="submit" class="btn btn-primary me-2" disabled="@isSaving">
                        @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Save
                    </button>
                    <button type="button" class="btn btn-outline-secondary" @onclick="CancelForm">Cancel</button>
                </EditForm>
            </div>
        </div>
    }

    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="filterStatus">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
    </div>

    @if (isLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Customer</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><code>@s.TrackingNumber</code></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.CustomerEmail</td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>
                                <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(s)">Edit</button>
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => DeleteShipment(s.Id)">Delete</button>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        @if (!FilteredShipments.Any())
        {
            <p class="text-muted text-center">No shipments found.</p>
        }
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private ShipmentDto editingShipment = new();
    private bool showForm;
    private bool isLoading = true;
    private bool isSaving;
    private string? errorMessage;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrEmpty(filterText) &&
            !s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            return false;

        if (!string.IsNullOrEmpty(filterStatus) &&
            Enum.TryParse<ShipmentStatus>(filterStatus, out var status) &&
            s.Status != status)
            return false;

        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto
        {
            TrackingNumber = $"SHP-{DateTime.UtcNow:yyyy}-{Random.Shared.Next(100, 999):000}",
            Status = ShipmentStatus.Pending,
            EstimatedDelivery = DateTime.UtcNow.AddDays(5)
        };
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail,
            Notes = shipment.Notes
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        isSaving = true;
        errorMessage = null;

        try
        {
            bool success;
            if (editingShipment.Id == 0)
                success = await ShipmentService.CreateShipmentAsync(editingShipment);
            else
                success = await ShipmentService.UpdateShipmentAsync(editingShipment);

            if (success)
            {
                showForm = false;
                await LoadShipments();
            }
            else
            {
                errorMessage = "Failed to save shipment. Please try again.";
            }
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task DeleteShipment(int id)
    {
        var success = await ShipmentService.DeleteShipmentAsync(id);
        if (success)
            await LoadShipments();
        else
            errorMessage = "Failed to delete shipment.";
    }

    private void CancelForm() => showForm = false;

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}
