    <h2>🔍 Track Your Shipment</h2>
    <p>Enter your tracking number below to check shipment status and estimated delivery.</p>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="e.g. SHP-2026-001"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                    @if (isLoading)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Track
                </button>
            </div>
        </div>
    </div>

    @if (searchPerformed && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
        </div>
    }

    @if (shipment is not null)
    {
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>@shipment.TrackingNumber</strong>
                <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <p><strong>Origin:</strong> @shipment.Origin</p>
                        <p><strong>Destination:</strong> @shipment.Destination</p>
                    </div>
                    <div class="col-md-6">
                        <p><strong>Shipped:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy")</p>
                        <p><strong>Estimated Delivery:</strong>
                            @(shipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")
                        </p>
                    </div>
                </div>
                @if (!string.IsNullOrEmpty(shipment.Notes))
                {
                    <p class="mt-2"><strong>Notes:</strong> @shipment.Notes</p>
                }

                <div class="mt-3">
                    <h6>Shipment Progress</h6>
                    <div class="progress" style="height: 25px;">
                        <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                             role="progressbar"
                             style="width: @(GetProgressPercentage(shipment.Status))%"
                             aria-valuenow="@GetProgressPercentage(shipment.Status)"
                             aria-valuemin="0" aria-valuemax="100">
                            @shipment.Status
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool isLoading;
    private bool searchPerformed;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        isLoading = true;
        searchPerformed = true;
        searchedNumber = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.TrackShipmentAsync(searchedNumber);
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 100,
        _ => 0
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<div class="container mt-4">
    <h2>📊 My Shipments</h2>
    <p>View all shipments associated with your account.</p>

    @if (isLoading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (shipments.Count == 0)
    {
        <div class="alert alert-info">You don't have any shipments yet.</div>
    }
    else
    {
        <div class="row mb-3">
            <div class="col-md-4">
                <select class="form-select" @bind="filterStatus">
                    <option value="">All Statuses</option>
                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                    {
                        <option value="@status">@status</option>
                    }
                </select>
            </div>
        </div>

        @foreach (var s in FilteredShipments)
        {
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@s.TrackingNumber</strong>
                    <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-4">
                            <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                            <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        </div>
                        <div class="col-md-4">
                            <p class="mb-1"><strong>Shipped:</strong> @s.CreatedAt.ToString("MMM dd, yyyy")</p>
                            <p class="mb-1"><strong>Est. Delivery:</strong> @(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</p>
                        </div>
                        <div class="col-md-4">
                            @if (!string.IsNullOrEmpty(s.Notes))
                            {
                                <p class="mb-1"><strong>Notes:</strong> @s.Notes</p>
                            }
                        </div>
                    </div>
                    <div class="progress mt-2" style="height: 20px;">
                        <div class="progress-bar @GetProgressBarClass(s.Status)"
                             role="progressbar"
                             style="width: @(GetProgressPercentage(s.Status))%">
                            @s.Status
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string filterStatus = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrEmpty(filterStatus) &&
            Enum.TryParse<ShipmentStatus>(filterStatus, out var status) &&
            s.Status != status)
            return false;
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 100,
        _ => 0
    };
}
